function solve({config,state,event}){
  var gs=config.groups,ps=config.panels,s=state;
  if(!s){
    s={r:[],o:[],en:[]};
    for(var i=0;i<gs.length;i++){s.r[i]=!!gs[i].required;s.o[i]=null}
    for(i=0;i<ps.length;i++)s.en[i]=!!ps[i].enabled;
    for(i=0;i<gs.length;i++)if(s.r[i])for(var j=0;j<ps.length;j++)if(ps[j].group===gs[i].id&&s.en[j]){s.o[i]=ps[j].id;break}
  }else for(var i=0;i<ps.length;i++)if(typeof s.en[i]!=='boolean')s.en[i]=!!ps[i].enabled;
  var gi=-1,pi=-1,e=event||{};
  if(e.type==='toggle'){
    for(var i=0;i<ps.length;i++)if(ps[i].id===e.id){pi=i;break}
    if(pi>=0&&s.en[pi]){for(i=0;i<gs.length;i++)if(gs[i].id===ps[pi].group){gi=i;break}if(gi>=0){if(s.o[gi]===ps[pi].id){if(!s.r[gi])s.o[gi]=null}else s.o[gi]=ps[pi].id}}
  }else if(e.type==='enabled'){
    for(var i=0;i<ps.length;i++)if(ps[i].id===e.id){s.en[i]=!!e.value;break}
  }else if(e.type==='close'){
    for(var i=0;i<gs.length;i++)if(gs[i].id===e.group&& !s.r[i]){s.o[i]=null;break}
  }else if(e.type==='mode'){
    for(var i=0;i<gs.length;i++)if(gs[i].id===e.group){s.r[i]=!!e.required;break}
  }
  for(var i=0;i<gs.length;i++){
    if(s.o[i]!==null){var ok=false;for(var j=0;j<ps.length;j++)if(ps[j].id===s.o[i]&&s.en[j]){ok=true;break}if(!ok)s.o[i]=null}
    if(s.o[i]===null&&s.r[i])for(var j=0;j<ps.length;j++)if(ps[j].group===gs[i].id&&s.en[j]){s.o[i]=ps[j].id;break}
  }
  var open={},uns=[],exp=[];
  for(var i=0;i<gs.length;i++){open[gs[i].id]=s.o[i];if(s.r[i]&&s.o[i]===null)uns.push(gs[i].id)}
  uns.sort();
  for(var j=0;j<ps.length;j++)for(var i=0;i<s.o.length;i++)if(s.o[i]===ps[j].id){exp.push(ps[j].id);break}
  return {state:s,output:{open:open,expanded:exp,unsatisfied:uns}};
}
